-- =====================================================================
-- cad_mirror  Structural change 0001  The CAD views mirrored by DS (DD-90 · CAD mirror specification v0.5)
-- Generated by tools/cad_mirror_ddl.py from the CAD structure workbook in 3rd API/; do not edit by hand.
-- Every table of the workbook, all columns. Types are mapped wide on purpose (a write must never fail on a
-- type); staging tightens them.
-- Run as cad_mirror_owner (run_as: owner); everything created here belongs to it.
-- =====================================================================
CREATE SCHEMA cad;
CREATE SCHEMA cad_meta;

-- The two mirror columns are ours, maintained by this trigger whatever the writer sends (DD-90):
--   mirror_inserted_at  set once, on INSERT
--   mirror_updated_at   the watermark column: moves only when the row's content really changed
-- An UPSERT that re-writes a row unchanged returns NULL here, so no new row version is written and the
-- watermark does not move: a re-sent day or a full re-load by DS creates no false changes (DD-78).
-- clock_timestamp() is not the commit time; the ingestion window is fenced by the heartbeat (DD-90).
CREATE FUNCTION cad.set_mirror_ts() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.mirror_inserted_at := clock_timestamp();
        NEW.mirror_updated_at  := NEW.mirror_inserted_at;
        RETURN NEW;
    END IF;
    NEW.mirror_inserted_at := OLD.mirror_inserted_at;
    NEW.mirror_updated_at  := OLD.mirror_updated_at;
    IF NEW IS NOT DISTINCT FROM OLD THEN
        RETURN NULL;
    END IF;
    NEW.mirror_updated_at := clock_timestamp();
    RETURN NEW;
END $$;

