    mirror_inserted_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    mirror_updated_at  timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (lsh)
);
CREATE INDEX ix_t_coderules_mirror_upd ON cad.t_coderules (mirror_updated_at);
CREATE TRIGGER trg_t_coderules_mirror_ts BEFORE INSERT OR UPDATE ON cad.t_coderules FOR EACH ROW EXECUTE FUNCTION cad.set_mirror_ts();

