-- heartbeat and reconciliation tables (spec section 5)
CREATE TABLE cad_meta.sync_heartbeat (
    sync_id          bigint PRIMARY KEY,
    started_at       timestamp NOT NULL,
    finished_at      timestamp NOT NULL,
    source_watermark timestamp,
    table_counts     jsonb,
    status           text NOT NULL CHECK (status IN ('ok','partial','failed')),
    message          text,
    received_at      timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE cad_meta.source_daily_count (
    business_date    date NOT NULL,
    table_name       text NOT NULL,
    row_count        bigint NOT NULL,
    reported_at      timestamp NOT NULL,
    received_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (business_date, table_name)
);

-- Privileges (LD-07 2.1). The DS writer: read, insert and update the mirror, insert heartbeat and counts; no
-- CREATE, DELETE, TRUNCATE, TRIGGER, REFERENCES. Our ingestion: read only. CONNECT is granted per database by
-- 41-cad-mirror.yml. Default privileges cover tables a later change adds.
GRANT USAGE ON SCHEMA cad, cad_meta TO cad_mirror_writer, oss911_ingest;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA cad TO cad_mirror_writer;
GRANT INSERT ON ALL TABLES IN SCHEMA cad_meta TO cad_mirror_writer;
GRANT SELECT ON ALL TABLES IN SCHEMA cad, cad_meta TO oss911_ingest;
ALTER DEFAULT PRIVILEGES FOR ROLE cad_mirror_owner IN SCHEMA cad GRANT SELECT, INSERT, UPDATE ON TABLES TO cad_mirror_writer;
ALTER DEFAULT PRIVILEGES FOR ROLE cad_mirror_owner IN SCHEMA cad_meta GRANT INSERT ON TABLES TO cad_mirror_writer;
ALTER DEFAULT PRIVILEGES FOR ROLE cad_mirror_owner IN SCHEMA cad, cad_meta GRANT SELECT ON TABLES TO oss911_ingest;
REVOKE EXECUTE ON FUNCTION cad.set_mirror_ts() FROM PUBLIC;
